record.field:
{"required": [
                {"key": "_init.owner_email", "label": "n8n Admin Email", "type": "text",
                "placeholder": "you@example.com", "description": "n8n 管理員登入 Email"},
                {"key": "_init.owner_password", "label": "n8n Admin Password", "type": "password",
                "description": "至少 8 字元，需含大小寫字母與數字"}
                ], "optional": [
                {"key": "config.database.type", "label": "Database Type", "type": "select",
                "default": "sqlite", "options": ["sqlite", "postgres"]},
                {"key": "main.config.GENERIC_TIMEZONE", "label": "Timezone", "type": "select",
                "default": "Asia/Taipei", "options": ["Asia/Taipei", "Asia/Tokyo", "Asia/Shanghai",
                "Asia/Hong_Kong", "America/New_York", "America/Los_Angeles", "Europe/London", "UTC"]},
                {"key": "main.config.N8N_LOG_LEVEL", "label": "Log Level", "type": "select",
                "default": "info", "options": ["info", "warn", "error", "debug"]}
                ]}

{"required": [
                {"key": "conf.adminEmail", "label": "Administrator Email", "type": "text",
                "placeholder": "you@example.com",
                "description": "Login email for the Odoo administrator. The initial password is generated by the platform and shown once after creation."}
                ], "optional": [
                {"key": "loadDemoData", "label": "Load Demo Data", "type": "boolean",
                "default": false}
                ]}

{"required": [], "optional": [
                {"key": "auth.anthropicApiKey", "label": "Anthropic API Key", "type": "password",
                "description": "自帶 Claude API Key（選填）；留空則於 console TUI 互動執行 claude login（登入態存 od-home）"},
                {"key": "auth.openrouterApiKey", "label": "OpenRouter API Key", "type": "password",
                "description": "容器內 OpenCode 使用的伺服器端 OpenRouter Key（選填）；填了就預設用 OpenCode，修改後服務會自動重啟（約 1–2 分鐘）；網頁介面自行輸入的 BYOK Key 不受影響"}
                ]}

{"required": [], "optional": [
                {"key": "auth.minimaxApiKey", "label": "MiniMax API Key", "type": "password",
                "description": "自帶 MiniMax API Key（選填）；存入 Kubernetes Secret 並以環境變數注入 agent，不寫入磁碟"},
                {"key": "auth.openrouterApiKey", "label": "OpenRouter API Key", "type": "password",
                "description": "自帶 OpenRouter API Key（選填）；供 agent 的 model routes 使用，同樣只存於 Secret"}
                ]}

{"required": [], "optional": [
                {"key": "auth.openrouterApiKey", "label": "OpenRouter API Key", "type": "password",
                "description": "雲端工作機使用的 OpenRouter Key（選填）；pi 用 Kimi／DeepSeek／Claude 等模型，未填 Anthropic Key 時 Claude Code 也經 OpenRouter。⚠ 金鑰會以環境變數注入每台雲端工作機，工作階段裡的程式、AI 代理與能開工作階段的成員都讀得到：請用有額度上限的專用子金鑰，移除成員後請更換。儲存後服務約一分鐘重啟，新開的工作階段生效"},
                {"key": "auth.anthropicApiKey", "label": "Anthropic API Key", "type": "password",
                "description": "雲端工作機上 Claude Code 使用的 Anthropic Key（選填，優先於 OpenRouter）；未填 OpenRouter 時 pi 也用它。⚠ 金鑰會以環境變數注入每台雲端工作機，工作階段裡的程式、AI 代理與能開工作階段的成員都讀得到：請用有用量上限的專用金鑰，移除成員後請更換。儲存後服務約一分鐘重啟，新開的工作階段生效"}
                ]}

{"required": [], "optional": [
                {"key": "litellm.spendLogRetention", "label": "用量明細保留天數", "type": "select", "default": "90d",
                "options": [{"value": "7d", "label": "7 天"}, {"value": "30d", "label": "30 天"}, {"value": "90d", "label": "90 天"}, {"value": "180d", "label": "180 天"}, {"value": "365d", "label": "365 天"}],
                "description": "每筆請求的明細紀錄（資料庫成長的主因）保留多久，超過的自動刪除。在 LiteLLM 後台改這項不會生效，請在這裡設定"},
                {"key": "litellm.apiDocs", "label": "API 說明頁（/docs）", "type": "boolean", "default": true,
                "description": "開啟時任何人都能看到 /docs、/redoc 的 API 說明頁（只列出端點，呼叫仍需金鑰）；關閉後這些頁面回 404"}
                ]}
